// OVERRIDE FOR OPENSTREETMAP AND GOOGLE MAPS DIRECT LINKS
function initContactOfficeSelector() {
    const selectorButtons = Array.from(document.querySelectorAll(".contact-selector-btn"));
    const officePanels = Array.from(document.querySelectorAll(".contact-office[data-office-panel]"));
    const mapFrame = document.getElementById("contact-map");
    const mapLinks = Array.from(document.querySelectorAll("[data-map-link]"));
    const mapTitleEl = document.getElementById("map-office-label");
    const mapOpenLink = document.getElementById("map-open-link");
    const mapDirLink = document.getElementById("map-dir-link");

    if (!selectorButtons.length || !officePanels.length) {
        return;
    }

    const availableOffices = new Set(officePanels.map((panel) => panel.dataset.officePanel));
    const mapSources = {
        malaga: "https://www.openstreetmap.org/export/embed.html?bbox=-4.474%2C36.694%2C-4.454%2C36.704&layer=mapnik&marker=36.6994%2C-4.4642",
        marbella: "https://www.openstreetmap.org/export/embed.html?bbox=-4.931%2C36.503%2C-4.911%2C36.513&layer=mapnik&marker=36.5082%2C-4.9213",
    };
    const locationLinks = {
        malaga: "https://www.google.com/maps/search/?api=1&query=36.6994,-4.4642",
        marbella: "https://www.google.com/maps/search/?api=1&query=36.5082,-4.9213",
    };
    const directionsLinks = {
        malaga: "https://www.google.com/maps/dir/?api=1&destination=36.6994,-4.4642",
        marbella: "https://www.google.com/maps/dir/?api=1&destination=36.5082,-4.9213",
    };
    const officeLabels = {
        malaga: "Sede Central Málaga — Pol. Ind. El Viso",
        marbella: "Delegación Marbella — C.C. Expo Marbella",
    };

    mapLinks.forEach((link) => {
        const office = link.getAttribute("data-map-link") || "";
        const targetUrl = locationLinks[office] || "#";
        link.setAttribute("href", targetUrl);
    });

    const setActiveOffice = (requestedOffice, shouldTrack = false) => {
        const office = availableOffices.has(requestedOffice)
            ? requestedOffice
            : (officePanels[0].dataset.officePanel || "malaga");

        selectorButtons.forEach((button) => {
            const isActive = button.dataset.office === office;
            button.classList.toggle("is-active", isActive);
            button.setAttribute("aria-pressed", String(isActive));
        });

        officePanels.forEach((panel) => {
            panel.hidden = panel.dataset.officePanel !== office;
        });

        if (mapFrame) {
            const nextSrc = mapSources[office] || "";
            if (nextSrc && mapFrame.getAttribute("src") !== nextSrc) {
                mapFrame.setAttribute("src", nextSrc);
            }
            mapFrame.setAttribute("title", office === "marbella" ? "Mapa oficial ATEL SISTEMS - Delegación Marbella" : "Mapa oficial ATEL SISTEMS - Sede Central Málaga");
        }

        if (mapTitleEl) {
            mapTitleEl.textContent = officeLabels[office] || "";
        }
        if (mapOpenLink) {
            mapOpenLink.setAttribute("href", locationLinks[office] || "#");
        }
        if (mapDirLink) {
            mapDirLink.setAttribute("href", directionsLinks[office] || "#");
        }

        if (shouldTrack) {
            trackEvent("contact_office_change", {
                elementId: "contact-office-selector",
                elementText: office,
            });
        }
    };

    selectorButtons.forEach((button) => {
        button.addEventListener("click", () => {
            setActiveOffice(button.dataset.office || "malaga", true);
        });
    });

    const initialOffice = selectorButtons.find((button) => button.classList.contains("is-active"))?.dataset.office
        || selectorButtons[0]?.dataset.office
        || "malaga";

    setActiveOffice(initialOffice, false);
}
initContactOfficeSelector();
